import * as React from "react";
import { Page, Card, BlockStack } from "@xco-agency/corex-ui";
import { ResourceEmptyState } from "../partials/ResourceEmptyState";
import { ResourceViewTabs } from "../partials/ResourceViewTabs";
import { RESOURCE_TABS } from "../constants";
import type { ResourceTabIdType } from "../types";

export function ResourceEmptyExample() {
  const [selectedTab, setSelectedTab] =
    React.useState<ResourceTabIdType>("all");

  const emptyTabs = RESOURCE_TABS.map((tab) => ({
    ...tab,
    count: 0,
  }));

  return (
    <Page
      heading="Products"
      subheading="Manage all catalog items, inventory levels, variants, and statuses."
      inlineSize="large"
      primaryAction={{
        content: "Add product",
        onAction: () => {},
      }}
    >
      <BlockStack gap="base">
        <Card padding="none">
          <ResourceViewTabs
            tabs={emptyTabs}
            selectedTab={selectedTab}
            onSelectTab={setSelectedTab}
          />
          <ResourceEmptyState
            type="zero-records"
            onCreateResource={() => {}}
          />
        </Card>
      </BlockStack>
    </Page>
  );
}

import * as React from "react";
import { Page, Card, BlockStack } from "@xco-agency/corex-ui";
import {
  DEFAULT_PAGE_SIZE,
  MOCK_RESOURCES,
  RESOURCE_CATEGORIES,
} from "../constants";
import { ResourceBulkActions } from "../partials/ResourceBulkActions";
import { ResourceEmptyState } from "../partials/ResourceEmptyState";
import { ResourceFilters } from "../partials/ResourceFilters";
import { ResourcePagination } from "../partials/ResourcePagination";
import { ResourceTable } from "../partials/ResourceTable";
import { ResourceViewTabs } from "../partials/ResourceViewTabs";
import type {
  ResourceFiltersType,
  ResourceItemType,
  ResourceStatusType,
  ResourceTabIdType,
  ResourceTabItemType,
} from "../types";

export function ResourceTableExample() {
  const [items, setItems] = React.useState<ResourceItemType[]>(MOCK_RESOURCES);
  const [filters, setFilters] = React.useState<ResourceFiltersType>({
    query: "",
    tab: "all",
    status: "all",
    category: "All categories",
  });
  const [currentPage, setCurrentPage] = React.useState(1);
  const [selectedIds, setSelectedIds] = React.useState<Set<string>>(new Set());

  const hasActiveFilters =
    filters.query !== "" ||
    filters.status !== "all" ||
    filters.category !== "All categories";

  const handleQueryChange = (query: string) => {
    setFilters((prev) => ({ ...prev, query }));
    setCurrentPage(1);
  };

  const handleStatusChange = (status: string) => {
    setFilters((prev) => ({ ...prev, status }));
    setCurrentPage(1);
  };

  const handleCategoryChange = (category: string) => {
    setFilters((prev) => ({ ...prev, category }));
    setCurrentPage(1);
  };

  const handleTabChange = (tab: ResourceTabIdType) => {
    setFilters((prev) => ({ ...prev, tab }));
    setCurrentPage(1);
  };

  const handleClearFilters = () => {
    setFilters({
      query: "",
      tab: "all",
      status: "all",
      category: "All categories",
    });
    setCurrentPage(1);
  };

  const filteredItems = React.useMemo(() => {
    return items.filter((item) => {
      // Tab filter
      if (filters.tab !== "all" && item.status !== filters.tab) {
        return false;
      }
      // Status dropdown filter
      if (filters.status !== "all" && item.status !== filters.status) {
        return false;
      }
      // Category dropdown filter
      if (
        filters.category !== "All categories" &&
        item.category !== filters.category
      ) {
        return false;
      }
      // Search query
      if (filters.query.trim()) {
        const q = filters.query.toLowerCase();
        const matchesTitle = item.title.toLowerCase().includes(q);
        const matchesSku = item.sku.toLowerCase().includes(q);
        const matchesVendor = item.vendor.toLowerCase().includes(q);
        if (!matchesTitle && !matchesSku && !matchesVendor) {
          return false;
        }
      }
      return true;
    });
  }, [items, filters]);

  const tabsWithCounts: ResourceTabItemType[] = React.useMemo(() => {
    return [
      { id: "all", content: "All", count: items.length },
      {
        id: "active",
        content: "Active",
        count: items.filter((i) => i.status === "active").length,
      },
      {
        id: "draft",
        content: "Draft",
        count: items.filter((i) => i.status === "draft").length,
      },
      {
        id: "archived",
        content: "Archived",
        count: items.filter((i) => i.status === "archived").length,
      },
    ];
  }, [items]);

  const totalPages = Math.ceil(filteredItems.length / DEFAULT_PAGE_SIZE);
  const paginatedItems = React.useMemo(() => {
    const startIndex = (currentPage - 1) * DEFAULT_PAGE_SIZE;
    return filteredItems.slice(startIndex, startIndex + DEFAULT_PAGE_SIZE);
  }, [filteredItems, currentPage]);

  const pageIds = paginatedItems.map((i) => i.id);
  const allSelected =
    pageIds.length > 0 && pageIds.every((id) => selectedIds.has(id));
  const someSelected =
    pageIds.some((id) => selectedIds.has(id)) && !allSelected;

  const handleToggleSelectAll = () => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (allSelected) {
        pageIds.forEach((id) => next.delete(id));
      } else {
        pageIds.forEach((id) => next.add(id));
      }
      return next;
    });
  };

  const handleToggleSelectItem = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  const handleBulkStatusChange = (status: ResourceStatusType) => {
    setItems((prev) =>
      prev.map((item) =>
        selectedIds.has(item.id) ? { ...item, status } : item,
      ),
    );
    setSelectedIds(new Set());
  };

  const handleBulkDelete = () => {
    setItems((prev) => prev.filter((item) => !selectedIds.has(item.id)));
    setSelectedIds(new Set());
  };

  const handleItemStatusChange = (id: string, status: ResourceStatusType) => {
    setItems((prev) =>
      prev.map((item) => (item.id === id ? { ...item, status } : item)),
    );
  };

  const handleDeleteItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
    setSelectedIds((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  const handleAddProduct = () => {
    const newId = `prod-${Date.now()}`;
    const newItem: ResourceItemType = {
      id: newId,
      title: "New Artisan Ceramic Mug",
      sku: `CER-MUG-${Math.floor(100 + Math.random() * 900)}`,
      vendor: "Studio Terra",
      category: "Home & Kitchen",
      status: "active",
      inventory: 25,
      price: "$34.00",
      imageUrl:
        "https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=100&h=100&fit=crop",
      updatedAt: "Just now",
    };
    setItems((prev) => [newItem, ...prev]);
  };

  return (
    <Page
      heading="Products"
      subheading="Manage all catalog items, inventory levels, variants, and statuses."
      inlineSize="large"
      primaryAction={{
        content: "Add product",
        onAction: handleAddProduct,
      }}
    >
      <BlockStack gap="base">
        <Card padding="none">
          {/* Status Tabs */}
          <ResourceViewTabs
            tabs={tabsWithCounts}
            selectedTab={filters.tab}
            onSelectTab={handleTabChange}
          />

          {/* Search and Filters */}
          <ResourceFilters
            filters={filters}
            categories={RESOURCE_CATEGORIES}
            hasActiveFilters={hasActiveFilters}
            onQueryChange={handleQueryChange}
            onStatusChange={handleStatusChange}
            onCategoryChange={handleCategoryChange}
            onClearFilters={handleClearFilters}
          />

          {/* Contextual Bulk Action Bar */}
          <ResourceBulkActions
            selectedCount={selectedIds.size}
            totalCount={items.length}
            onDeselectAll={() => setSelectedIds(new Set())}
            onBulkStatusChange={handleBulkStatusChange}
            onBulkDelete={handleBulkDelete}
          />

          {/* Data Table or Empty State */}
          {filteredItems.length === 0 ? (
            <ResourceEmptyState
              type="no-results"
              query={filters.query}
              onClearFilters={handleClearFilters}
            />
          ) : (
            <>
              <ResourceTable
                items={paginatedItems}
                selectedIds={selectedIds}
                allSelected={allSelected}
                indeterminate={someSelected}
                onToggleSelectAll={handleToggleSelectAll}
                onToggleSelectItem={handleToggleSelectItem}
                onDeleteItem={handleDeleteItem}
                onStatusChange={handleItemStatusChange}
              />

              <ResourcePagination
                currentPage={currentPage}
                totalPages={totalPages}
                totalItems={filteredItems.length}
                pageSize={DEFAULT_PAGE_SIZE}
                onPreviousPage={() =>
                  setCurrentPage((p) => Math.max(1, p - 1))
                }
                onNextPage={() =>
                  setCurrentPage((p) => Math.min(totalPages, p + 1))
                }
              />
            </>
          )}
        </Card>
      </BlockStack>
    </Page>
  );
}

export * from "./types";
export * from "./constants";
export { ResourceViewTabs } from "./partials/ResourceViewTabs";
export { ResourceFilters } from "./partials/ResourceFilters";
export { ResourceBulkActions } from "./partials/ResourceBulkActions";
export { ResourceTable } from "./partials/ResourceTable";
export { ResourceTableRow } from "./partials/ResourceTableRow";
export { ResourcePagination } from "./partials/ResourcePagination";
export { ResourceEmptyState } from "./partials/ResourceEmptyState";
export { ResourceTableExample } from "./examples/ResourceTableExample";
export { ResourceEmptyExample } from "./examples/ResourceEmptyExample";

import * as React from "react";
import { EmptyState, Text } from "@xco-agency/corex-ui";
import type { ResourceEmptyStatePropsType } from "../types";

export function ResourceEmptyState({
  type,
  query,
  onClearFilters,
  onCreateResource,
}: ResourceEmptyStatePropsType) {
  if (type === "no-results") {
    return (
      <EmptyState
        heading="No resources found"
        image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
        action={
          onClearFilters
            ? {
                content: "Clear all filters",
                onAction: onClearFilters,
                variant: "secondary",
              }
            : undefined
        }
        padding="large-100"
      >
        <Text as="p" tone="neutral" variant="small">
          {query
            ? `No resources matching "${query}". Try searching for another keyword or clearing applied filters.`
            : "No resources found matching the selected filter criteria. Try adjusting your filters to see results."}
        </Text>
      </EmptyState>
    );
  }

  return (
    <EmptyState
      heading="Manage your products & inventory"
      image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
      action={
        onCreateResource
          ? {
              content: "Add product",
              onAction: onCreateResource,
              variant: "primary",
            }
          : undefined
      }
      secondaryAction={{
        content: "Import products",
        variant: "secondary",
      }}
      padding="large-100"
    >
      <Text as="p" tone="neutral" variant="small">
        Track inventory levels, variants, pricing, and fulfillment across your
        entire catalog from one centralized dashboard.
      </Text>
    </EmptyState>
  );
}

import * as React from "react";
import {
  Box,
  InlineStack,
  BlockStack,
  SearchField,
  Select,
  Button,
} from "@xco-agency/corex-ui";
import type { ResourceFiltersPropsType } from "../types";

export function ResourceFilters({
  filters,
  categories,
  hasActiveFilters,
  onQueryChange,
  onStatusChange,
  onCategoryChange,
  onClearFilters,
}: ResourceFiltersPropsType) {
  const statusOptions = [
    { label: "All statuses", value: "all" },
    { label: "Active", value: "active" },
    { label: "Draft", value: "draft" },
    { label: "Archived", value: "archived" },
  ];

  const categoryOptions = categories.map((cat) => ({
    label: cat,
    value: cat,
  }));

  return (
    <Box paddingInline="base" paddingBlock="small-300">
      <InlineStack
        gap="base"
        alignItems="center"
        justifyContent="space-between"
        wrap
      >
        <BlockStack grow minInlineSize="240px">
          <SearchField
            placeholder="Search by title, SKU, or vendor..."
            value={filters.query}
            onChange={(val) => onQueryChange(val)}
            onClear={() => onQueryChange("")}
          />
        </BlockStack>

        <InlineStack gap="small-300" alignItems="center" wrap>
          <Box minInlineSize="140px">
            <Select
              label="Status"
              value={filters.status}
              options={statusOptions}
              onChange={(val) => onStatusChange(val)}
            />
          </Box>

          <Box minInlineSize="160px">
            <Select
              label="Category"
              value={filters.category}
              options={categoryOptions}
              onChange={(val) => onCategoryChange(val)}
            />
          </Box>

          {hasActiveFilters && (
            <Button variant="tertiary" onClick={onClearFilters}>
              Clear filters
            </Button>
          )}
        </InlineStack>
      </InlineStack>
    </Box>
  );
}

import * as React from "react";
import {
  BlockStack,
  InlineStack,
  Text,
  Button,
  ButtonGroup,
} from "@xco-agency/corex-ui";
import type { ResourcePaginationPropsType } from "../types";

export function ResourcePagination({
  currentPage,
  totalPages,
  totalItems,
  pageSize,
  onPreviousPage,
  onNextPage,
}: ResourcePaginationPropsType) {
  const fromIndex = totalItems === 0 ? 0 : (currentPage - 1) * pageSize + 1;
  const toIndex = Math.min(currentPage * pageSize, totalItems);

  return (
    <BlockStack
      padding="small-300"
      paddingInline="base"
      style={{
        borderTop: "1px solid var(--p-color-border-subdued)",
      }}
    >
      <InlineStack
        alignItems="center"
        justifyContent="space-between"
        wrap
        gap="base"
      >
        <Text as="span" variant="small" tone="neutral">
          {totalItems > 0
            ? `Showing ${fromIndex}–${toIndex} of ${totalItems} items`
            : "0 items"}
        </Text>

        <InlineStack gap="small-200" alignItems="center">
          <Text as="span" variant="xs" tone="neutral">
            Page {currentPage} of {Math.max(1, totalPages)}
          </Text>
          <ButtonGroup>
            <Button
              variant="secondary"
              disabled={currentPage <= 1}
              onClick={onPreviousPage}
            >
              Previous
            </Button>
            <Button
              variant="secondary"
              disabled={currentPage >= totalPages}
              onClick={onNextPage}
            >
              Next
            </Button>
          </ButtonGroup>
        </InlineStack>
      </InlineStack>
    </BlockStack>
  );
}

import * as React from "react";
import { Table, Checkbox, Box } from "@xco-agency/corex-ui";
import { ResourceTableRow } from "./ResourceTableRow";
import type { ResourceTablePropsType } from "../types";

export function ResourceTable({
  items,
  selectedIds,
  allSelected,
  indeterminate: _indeterminate,
  onToggleSelectAll,
  onToggleSelectItem,
  onDeleteItem,
  onStatusChange,
}: ResourceTablePropsType) {
  return (
    <Table variant="auto">
      <Table.HeaderRow>
        {/* Master Select All Checkbox */}
        <Table.Header>
          <Box paddingBlock="none">
            <Checkbox
              label=""
              checked={allSelected}
              onChange={onToggleSelectAll}
            />
          </Box>
        </Table.Header>
        <Table.Header listSlot="primary">Resource</Table.Header>
        <Table.Header listSlot="inline">Status</Table.Header>
        <Table.Header format="numeric">Inventory</Table.Header>
        <Table.Header format="currency">Price</Table.Header>
        <Table.Header>Category</Table.Header>
        <Table.Header>Updated</Table.Header>
        <Table.Header>
          <span style={{ display: "block", textAlign: "right" }}>Actions</span>
        </Table.Header>
      </Table.HeaderRow>

      <Table.Body>
        {items.map((item) => (
          <ResourceTableRow
            key={item.id}
            item={item}
            isSelected={selectedIds.has(item.id)}
            onToggleSelect={() => onToggleSelectItem(item.id)}
            onDelete={onDeleteItem ? () => onDeleteItem(item.id) : undefined}
            onStatusChange={
              onStatusChange
                ? (status) => onStatusChange(item.id, status)
                : undefined
            }
          />
        ))}
      </Table.Body>
    </Table>
  );
}

import * as React from "react";
import {
  Table,
  Checkbox,
  Thumbnail,
  Text,
  Badge,
  Button,
  InlineStack,
  BlockStack,
  Box,
} from "@xco-agency/corex-ui";
import type { ToneType } from "@xco-agency/corex-ui";
import type { ResourceStatusType, ResourceTableRowPropsType } from "../types";

const STATUS_TONE_MAP: Record<ResourceStatusType, ToneType> = {
  active: "success",
  draft: "info",
  archived: "neutral",
};

export function ResourceTableRow({
  item,
  isSelected,
  onToggleSelect,
  onDelete,
  onStatusChange,
}: ResourceTableRowPropsType) {
  const isLowInventory = item.status === "active" && item.inventory < 20;

  return (
    <Table.Row>
      {/* Selection checkbox */}
      <Table.Cell>
        <Box paddingBlock="none">
          <Checkbox
            label=""
            checked={isSelected}
            onChange={onToggleSelect}
          />
        </Box>
      </Table.Cell>

      {/* Primary resource column */}
      <Table.Cell>
        <InlineStack gap="small-300" alignItems="center">
          {item.imageUrl ? (
            <Thumbnail
              src={item.imageUrl}
              alt={item.title}
              size="small"
            />
          ) : (
            <InlineStack
              alignItems="center"
              justifyContent="center"
              style={{
                width: "40px",
                height: "40px",
                borderRadius: "var(--p-border-radius-100)",
                background: "var(--p-color-bg-surface-secondary)",
              }}
            >
              <Text as="span" variant="xs" tone="neutral">
                N/A
              </Text>
            </InlineStack>
          )}

          <BlockStack gap="none">
            <Text variant="base" heading lineClamp={1}>
              {item.title}
            </Text>
            <InlineStack gap="small-200" alignItems="center">
              <Text variant="xs" tone="neutral">
                SKU: {item.sku}
              </Text>
              <Text variant="xs" tone="neutral">
                •
              </Text>
              <Text variant="xs" tone="neutral">
                {item.vendor}
              </Text>
            </InlineStack>
          </BlockStack>
        </InlineStack>
      </Table.Cell>

      {/* Status */}
      <Table.Cell>
        <Badge tone={STATUS_TONE_MAP[item.status]}>
          {item.status.charAt(0).toUpperCase() + item.status.slice(1)}
        </Badge>
      </Table.Cell>

      {/* Inventory */}
      <Table.Cell>
        <BlockStack gap="none">
          <Text
            variant="small"
            tone={isLowInventory ? "warning" : "neutral"}
          >
            {item.inventory} in stock
          </Text>
          {isLowInventory && (
            <Text variant="xs" tone="warning">
              Low inventory
            </Text>
          )}
        </BlockStack>
      </Table.Cell>

      {/* Price */}
      <Table.Cell>
        <Text variant="small" heading>
          {item.price}
        </Text>
      </Table.Cell>

      {/* Category */}
      <Table.Cell>
        <Text variant="small" tone="neutral">
          {item.category}
        </Text>
      </Table.Cell>

      {/* Last updated */}
      <Table.Cell>
        <Text variant="xs" tone="neutral">
          {item.updatedAt}
        </Text>
      </Table.Cell>

      {/* Quick actions */}
      <Table.Cell>
        <InlineStack gap="small-200" justifyContent="end">
          {onStatusChange && (
            <Button
              variant="tertiary"
              onClick={() =>
                onStatusChange(
                  item.status === "active" ? "draft" : "active",
                )
              }
            >
              {item.status === "active" ? "Draft" : "Activate"}
            </Button>
          )}
          {onDelete && (
            <Button
              variant="tertiary"
              tone="critical"
              onClick={onDelete}
            >
              Delete
            </Button>
          )}
        </InlineStack>
      </Table.Cell>
    </Table.Row>
  );
}

import * as React from "react";
import { Box, Tabs } from "@xco-agency/corex-ui";
import type { TabItemType } from "@xco-agency/corex-ui";
import type { ResourceTabIdType, ResourceViewTabsPropsType } from "../types";

export function ResourceViewTabs({
  tabs,
  selectedTab,
  onSelectTab,
}: ResourceViewTabsPropsType) {
  const tabItems: TabItemType<ResourceTabIdType>[] = tabs.map((tab) => ({
    id: tab.id,
    label: tab.content,
    badge: tab.count !== undefined ? String(tab.count) : undefined,
  }));

  return (
    <Box paddingInline="base" paddingBlockStart="small-200" paddingBlockEnd="none">
      <Tabs<ResourceTabIdType>
        tabs={tabItems}
        value={selectedTab}
        onChange={(tabId) => onSelectTab(tabId)}
      />
    </Box>
  );
}

import type * as React from "react";

export type ResourceStatusType = "active" | "draft" | "archived";

export type ResourceItemType = {
  id: string;
  title: string;
  sku: string;
  vendor: string;
  category: string;
  status: ResourceStatusType;
  inventory: number;
  price: string;
  imageUrl?: string;
  updatedAt: string;
};

export type ResourceTabIdType = "all" | "active" | "draft" | "archived";

export type ResourceTabItemType = {
  id: ResourceTabIdType;
  content: string;
  count?: number;
};

export type ResourceFiltersType = {
  query: string;
  tab: ResourceTabIdType;
  status: string;
  category: string;
};

export type ResourceBulkActionType = {
  label: string;
  onAction: (selectedIds: string[]) => void;
  destructive?: boolean;
  disabled?: boolean;
};

export type ResourceViewTabsPropsType = {
  tabs: ResourceTabItemType[];
  selectedTab: ResourceTabIdType;
  onSelectTab: (tabId: ResourceTabIdType) => void;
};

export type ResourceFiltersPropsType = {
  filters: ResourceFiltersType;
  categories: string[];
  hasActiveFilters: boolean;
  onQueryChange: (query: string) => void;
  onStatusChange: (status: string) => void;
  onCategoryChange: (category: string) => void;
  onClearFilters: () => void;
};

export type ResourceBulkActionsPropsType = {
  selectedCount: number;
  totalCount: number;
  onDeselectAll: () => void;
  onBulkStatusChange: (status: ResourceStatusType) => void;
  onBulkDelete: () => void;
};

export type ResourceTablePropsType = {
  items: ResourceItemType[];
  selectedIds: Set<string>;
  allSelected: boolean;
  indeterminate: boolean;
  onToggleSelectAll: () => void;
  onToggleSelectItem: (id: string) => void;
  onDeleteItem?: (id: string) => void;
  onStatusChange?: (id: string, status: ResourceStatusType) => void;
};

export type ResourceTableRowPropsType = {
  item: ResourceItemType;
  isSelected: boolean;
  onToggleSelect: () => void;
  onDelete?: () => void;
  onStatusChange?: (status: ResourceStatusType) => void;
};

export type ResourcePaginationPropsType = {
  currentPage: number;
  totalPages: number;
  totalItems: number;
  pageSize: number;
  onPreviousPage: () => void;
  onNextPage: () => void;
};

export type ResourceEmptyStatePropsType = {
  type: "no-results" | "zero-records";
  query?: string;
  onClearFilters?: () => void;
  onCreateResource?: () => void;
};
